"""Original, individually authored bilingual pairs. No numeric expansion."""
import re


def p(category, english, chinese, context="", terms=None):
    if re.search(r"[\u4e00-\u9fff]", english) or not re.search(r"[\u4e00-\u9fff]", chinese):
        raise ValueError("此对照语料必须 English 在前、中文在后；混合语言样本应显式构造输入")
    return {"category": category, "english": english, "chinese": chinese,
            "context": context, "terms": terms or {}}


